import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class ArrayVsCollectionDemo {
    public static void main(String[] args) {
        // Array: Fixed size, primitive support, zero-overhead access
        int[] primitiveArray = new int[5];
        primitiveArray[0] = 42;
        int val = primitiveArray[0]; // O(1) direct memory offset access

        // Collection: Dynamic sizing, generics, rich API
        List<Integer> collectionList = new ArrayList<>();
        collectionList.add(42); // Autoboxing int to Integer
        collectionList.add(100);

        // Interoperability: Converting Array to Collection
        String[] stringArray = {"Alpha", "Beta", "Gamma"};
        List<String> fixedSizeList = Arrays.asList(stringArray);

        // Safe dynamic collection initialization
        List<String> mutableList = new ArrayList<>(Arrays.asList(stringArray));
        mutableList.add("Delta");
    }
}
